import {tenthsCases,TENTHS_HELP} from './tenths-content.mjs';
import {tenthsView,startTenths,toggleTenthsPart,clearTenths,supportTenths,checkTenths,keepTenths,recoverTenths} from './tenths-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(text,attrs,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${text}</button>`;
const notice='<p id="tenths-status" role="status" tabindex="-1"></p>';
const recovery=()=>`<p>Start a fresh table while keeping the entire earlier table, including readable cases, in notes.</p>${button('Keep earlier record and start a fresh table','data-tenths-recover')}`;
function chooser(v){return `<details class="tenths-chooser" ${v.work?'':'open'}><summary>Choose any request</summary><div class="tenths-requests">${tenthsCases.map((s,index)=>{const blocked=v.unreadable.some(x=>x.id===s.id);return `<article><h3>Request ${index+1}</h3><p>${esc(s.request)}</p>${blocked?'<p>This saved request cannot be opened here. It is kept in notes; other requests remain open.</p>':button(v.readable.some(x=>x.id===s.id)?'Return to this request':'Start this request',`data-tenths-start="${s.id}"`)}</article>`;}).join('')}</div></details>`;}
function older(v){return v.status==='recovery'?`<details><summary>Earlier table record</summary><pre>${esc(JSON.stringify(v.root,null,2))}</pre></details>`:v.unreadable.length?`<details><summary>Earlier unreadable requests (${v.unreadable.length})</summary><pre>${esc(JSON.stringify(v.unreadable,null,2))}</pre></details>`:'';}
function selectedPicture(selection,label='Saved selected parts'){return `<div class="tenths-mini" role="img" aria-label="${esc(label)}: ${selection.length} of ten parts"><span aria-hidden="true">${Array.from({length:10},(_,i)=>`<i class="${selection.includes(i)?'filled':''}"></i>`).join('')}</span></div>`;}
function earlier(v){return `<details class="tenths-history"><summary>Earlier checks and kept work</summary>${v.readable.map(({id,work:w})=>`<section><h3>${esc(w.source.title)}</h3><p>${esc(w.source.request)}</p>${!tenthsCases.some(s=>s.id===id)?button('Resume this earlier request',`data-tenths-start="${esc(id)}"`):''}${w.kept?`<article class="tenths-kept"><h4>Kept draft</h4>${selectedPicture(w.kept.selected)}<p>Support recorded: ${esc(w.kept.support.join(', ')||'none')}.</p>${w.kept.latestCheck?`<p>Check kept with this draft: ${esc(w.kept.latestCheck.feedbackText)}</p>`:'<p>This draft was kept without a check.</p>'}</article>`:''}${w.checks.map(c=>`<article><h4>Earlier check ${c.id}</h4>${selectedPicture(c.selected)}<p>${esc(c.feedbackText)}</p><p>Practice with a picture. ${c.familiar?'A familiar request or supplied equivalence.':'No earlier supplied equivalence recorded for this request.'} Support before this response: ${esc(c.support.join(', ')||'none')}.</p></article>`).join('')}${!w.kept&&!w.checks.length?'<p>No checks or kept work yet.</p>':''}</section>`).join('')}</details>`;}
export function tenthsPage(state){
 const v=tenthsView(state),w=v.work;
 const head='<section class="tenths-table" data-tenths-root><header><a class="back" href="#numbers">Back to Number Garden</a><p class="tenths-eyebrow">A repair-strip labeling table</p><h1 id="tenths-title" tabindex="-1">Tenths Table</h1><p>One whole strip can have two names for the same amount. Choose any request, make an amount, and check it together.</p></header>';
 if(v.status==='recovery')return head+'<h2>Earlier table work is kept</h2>'+recovery()+notice+older(v)+'</section>';
 let html=head+chooser(v);
 if(w){const c=w.checks.find(x=>x.id===w.feedbackId);html+=`<section class="tenths-work"><h2 id="tenths-request" tabindex="-1">${esc(w.source.title)}</h2><p class="tenths-request">${esc(w.source.request)}</p><div class="tenths-whole"><p>${esc(w.source.wholeLabel)}</p><div class="tenths-parts" role="group" aria-label="One whole strip, ten equal parts">${Array.from({length:10},(_,i)=>`<button type="button" class="tenths-part ${w.selected.includes(i)?'selected':''}" data-tenths-part="${i}" aria-label="Part ${i+1} of 10, ${w.selected.includes(i)?'selected':'not selected'}" aria-pressed="${w.selected.includes(i)}"><span aria-hidden="true">${i+1}</span></button>`).join('')}</div><p data-tenths-count>${w.selected.length} parts selected.</p></div><div class="tenths-actions">${button('Clear selection','data-tenths-clear')}${button('Check this amount',`data-tenths-check ${w.nextCheckId>=Number.MAX_SAFE_INTEGER?'disabled':''}`,true)}${button('Keep this draft','data-tenths-keep')}</div>${w.checks.length===4?'<p class="tenths-cap">The next check replaces the oldest of four retained checks for this request. Your kept draft stays. Download notes first to keep every check.</p>':''}${w.nextCheckId>=Number.MAX_SAFE_INTEGER?'<p>This request has reached its check limit. Earlier work remains available.</p>':''}${c?`<section class="tenths-feedback" id="tenths-feedback" tabindex="-1"><h3>Your checked amount</h3><p>${esc(c.feedbackText)}</p></section>`:''}<details class="tenths-help" ${w.helpOpen?'open':''}><summary>Help if you like</summary>${button('Show an explanation','data-tenths-help')}${button('We worked together',`data-tenths-together aria-pressed="${w.support.includes('together')}"`)}${hearButton(w.source.request,'Hear this request')}${w.helpOpen?`<p id="tenths-help-text" tabindex="-1">${esc(TENTHS_HELP)}</p>`:''}<p>At Bundle Exchange, ten ones make ten. Here, ten tenths make one whole. Our whole strip stays the same size.</p></details>${w.kept?'<p id="tenths-kept-status" tabindex="-1">A copy is kept in earlier checks and kept work. Later edits need another Keep.</p>':''}</section>`;}
 if(v.status==='ready'){html+=earlier(v)+older(v);if(v.unreadable.length)html+=recovery();if(Object.hasOwn(v.root,'recovered'))html+=`<details><summary>Whole earlier table kept for recovery</summary><pre>${esc(JSON.stringify(v.root.recovered,null,2))}</pre></details>`;}
 return html+notice+'<p><a href="#notes">Grown-up notes and download</a> · <a href="#cafe/fractions">Visit Fraction Trail</a> · <a href="#numbers/hundredths">Visit Hundredths Bridge</a></p><details><summary>For grown-ups</summary><p>This is pictured practice using supplied requests and explanations. It does not establish independent decimal writing, fluency, placement or mastery. Help and complete equivalent labels qualify later practice. No other game receives assessment evidence from this table.</p></details></section>';
}
export function tenthsEntry(){return '<section class="tenths-entry"><h2>Two names for one strip</h2><p>Make equal tenths and meet their decimal names.</p><a class="secondary" href="#numbers/tenths">Visit Tenths Table</a></section>';}
export function tenthsNotes(state){if(!Object.hasOwn(state,'tenthsTable'))return '';const v=tenthsView(state);return `<details class="panel"><summary>Tenths Table: supplied pictured practice</summary><p>Each request retains its original source. Checks, familiarity and support are practice records, not independent decimal knowledge.</p>${v.status==='recovery'?older(v):earlier(v)+older(v)}<pre>${esc(JSON.stringify(state.tenthsTable,null,2))}</pre></details>`;}
export function bindTenths(state,{save,render,focus,canExport}={}){
 const root=document.querySelector('[data-tenths-root]');if(!root)return;
 const status=message=>{const n=document.querySelector('#tenths-status');if(n){n.textContent=message;focus?.('#tenths-status');}};
 const refresh=target=>{save?.();render?.();focus?.(target);};
 const refusal='This table could not be added safely. Earlier work is unchanged. Download it from Grown-up notes, then start a separate explorer if needed.';
 root.querySelectorAll('[data-tenths-start]').forEach(b=>b.addEventListener('click',()=>{if(startTenths(state,b.dataset.tenthsStart,canExport))refresh('#tenths-request');else status(refusal);}));
 root.querySelectorAll('[data-tenths-part]').forEach(b=>b.addEventListener('click',()=>{if(toggleTenthsPart(state,Number(b.dataset.tenthsPart)))refresh(`[data-tenths-part="${b.dataset.tenthsPart}"]`);}));
 for(const [selector,fn,target] of [['[data-tenths-clear]',clearTenths,'[data-tenths-clear]'],['[data-tenths-check]',checkTenths,'#tenths-feedback'],['[data-tenths-keep]',keepTenths,'#tenths-kept-status']])root.querySelector(selector)?.addEventListener('click',()=>{if(fn(state))refresh(target);});
 root.querySelector('[data-tenths-help]')?.addEventListener('click',()=>{if(supportTenths(state,'help'))refresh('#tenths-help-text');});
 root.querySelector('[data-tenths-together]')?.addEventListener('click',()=>{if(supportTenths(state,'together')){save?.();render?.();const help=document.querySelector('.tenths-help');if(help)help.open=true;focus?.('[data-tenths-together]');}});
 root.querySelector('[data-tenths-recover]')?.addEventListener('click',()=>{if(recoverTenths(state,canExport))refresh('#tenths-request');else status(refusal);});
 root.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',()=>{if(supportTenths(state,'narrationRequested'))save?.();},{capture:true}));
}
